cypress_script:
describe('Alert and Confirm Dialogs', () => {
  it('should display alert dialog when alert button is clicked', () => {
    cy.visit('https://demoqa.com/alerts');
    cy.get('#alertButton').click();
    cy.on('window:alert', (str) => {
      expect(str).to.exist;
    });
  });

  it('should not change URL when confirm dialog is triggered', () => {
    cy.visit('https://demoqa.com/alerts');
    cy.get('#confirmButton').click();
    cy.on('window:confirm', (str) => {
      return true; // Simulate clicking OK
    });
    cy.url().should('eq', 'https://demoqa.com/alerts');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Alert and Confirm Dialogs', () => {
  test('should display alert dialog when alert button is clicked', async ({ page }) => {
    await page.goto('https://demoqa.com/alerts');
    await page.click('#alertButton');
    page.on('dialog', dialog => {
      expect(dialog.message()).toBeTruthy();
      dialog.dismiss();
    });
  });

  test('should not change URL when confirm dialog is triggered', async ({ page }) => {
    await page.goto('https://demoqa.com/alerts');
    await page.click('#confirmButton');
    page.on('dialog', dialog => {
      dialog.accept(); // Simulate clicking OK
    });
    expect(page.url()).toBe('https://demoqa.com/alerts');
  });
});
